} from './diagram_change_review_service'

/** Modal review shell. Changing one semantic change remains inside its row leaf. */
export function DiagramChangeReviewDialog({
    review = diagramChangeReviewService,
    save,
    session = diagramEditSessionService,
}: {
    review?: DiagramChangeReviewService
    save?: DiagramSaveService
    session?: DiagramEditSessionService
}) {
    const open = useSyncExternalStore(review.subscribeOpen, review.getOpenSnapshot, review.getOpenSnapshot)
    const handleClose = useCallback(() => review.close(), [review])

    return (
        <Dialog fullWidth maxWidth="md" onClose={handleClose} open={open}>
            <DialogTitle>Review diagram changes</DialogTitle>
            <DialogContent dividers>
                <Stack spacing={2}>
                    <DiagramChangeReviewList review={review} session={session} />
                    <DiagramChangeReviewReport review={review} />
                </Stack>
            </DialogContent>
            <DiagramChangeReviewActions review={review} save={save} session={session} />
        </Dialog>
    )
}

import { register } from '../service_injector'
import {
    diagramEditSessionService,
    type DiagramEditSessionService,
    type ReadonlyDiagramData,
} from './diagram_edit_session_service'
import { parseDiagramData, serializeDiagramData, type DiagramData } from './diagram_data'
import {
    diagramViewService,
    type DiagramViewService,
    type SaveEditedDiagramCopyRequest,
} from './diagram_view_service'

const SAVE_STATUS_CHANGED_EVENT = 'diagramSaveStatusChanged'

export type DiagramSaveStatus = 'idle' | 'saving'

type DiagramSaveSession = Pick<DiagramEditSessionService,
    | 'acknowledgeSavedCopy'
    | 'getDirtySnapshot'
    | 'getEditableDiagram'
    | 'getOriginalDiagramSnapshot'
    | 'getSavedRecordSnapshot'
    | 'getSessionSnapshot'
>

type DiagramCopyPersistence = Pick<DiagramViewService, 'saveEditedDiagramCopy'>
type DiagramSerializer = (diagram: ReadonlyDiagramData) => string

function canonicalDiagramContent(diagram: ReadonlyDiagramData) {
    return serializeDiagramData(diagram as DiagramData)
}

/** Owns explicit edited-diagram save progress and coordinates session acknowledgement. */
export class DiagramSaveService extends EventTarget {
    private readonly persistence: DiagramCopyPersistence
    private readonly serialize: DiagramSerializer
    private readonly session: DiagramSaveSession
    private status: DiagramSaveStatus = 'idle'

    constructor(
        session: DiagramSaveSession = diagramEditSessionService,
        persistence: DiagramCopyPersistence = diagramViewService,
        serialize: DiagramSerializer = canonicalDiagramContent,
    ) {
        super()
        this.persistence = persistence
        this.serialize = serialize
        this.session = session
    }

    getStatusSnapshot = () => this.status

    subscribeStatus = (listener: () => void) => {
        this.addEventListener(SAVE_STATUS_CHANGED_EVENT, listener)

        return () => this.removeEventListener(SAVE_STATUS_CHANGED_EVENT, listener)
    }

    async save() {
        if (this.status === 'saving') throw new Error('Diagram save is already in progress')
        if (!this.session.getDirtySnapshot()) throw new Error('Cannot save a diagram without changes')
        const editableDiagram = this.session.getEditableDiagram()
        const originalDiagram = this.session.getOriginalDiagramSnapshot()
        const editSession = this.session.getSessionSnapshot()
        if (!editableDiagram || !originalDiagram || !editSession) throw new Error('Cannot save without an active diagram edit session')

        const content = this.serialize(editableDiagram)
        const savedDiagram = parseDiagramData(content)
        const request: SaveEditedDiagramCopyRequest = {
            content,
            savedRecord: this.session.getSavedRecordSnapshot(),
            sourceRecord: originalDiagram.record,
        }
        this.setStatus('saving')
        try {
            const record = await this.persistence.saveEditedDiagramCopy(request)
            const currentSession = this.session.getSessionSnapshot()
            if (currentSession?.sourceDiagramId === editSession.sourceDiagramId) {
                const currentDiagram = this.session.getEditableDiagram()
                const savedDataIsCurrent = !!currentDiagram && this.serialize(currentDiagram) === content
                this.session.acknowledgeSavedCopy(record, savedDiagram, savedDataIsCurrent)
            }

            return record
        } finally {
            this.setStatus('idle')
        }
    }

    private setStatus(status: DiagramSaveStatus) {
        if (status === this.status) return

        this.status = status
        this.dispatchEvent(new Event(SAVE_STATUS_CHANGED_EVENT))
    }
}

export const diagramSaveService = register('diagramSaveService', new DiagramSaveService())

import { ListItemText, Menu, MenuItem } from '@mui/material'
import ChevronRight from 'mdi-material-ui/ChevronRight'
import { useMemo, useSyncExternalStore, type KeyboardEvent, type MouseEvent } from 'react'
import { actionsForContext, diagramContext } from '../../data/action_context'
import type { ActionDefinition } from '../../data/action_types'
import { dialogService } from '../../services/dialog_service'
import type { DiagramRecord } from '../../services/diagrams/diagram_index'
import type { DiagramItemSubmenuKind, DiagramViewService } from '../../services/diagrams/diagram_view_service'
import { useActions } from '../hooks/use_actions'
import {
    diagramEmphasisService, type DiagramEmphasisService,
} from '../../services/diagrams/diagram_emphasis_service'

interface DiagramItemMenuProps {
    emphasis?: Pick<DiagramEmphasisService, 'emphasize'>
    service: Pick<DiagramViewService,
        'closeItemMenu'
        | 'closeItemSubmenu'
        | 'getMenuSnapshot'
        | 'getSavedChildren'
        | 'navigateToSavedDiagram'
        | 'openChildPopup'
        | 'openItemSubmenu'
        | 'subscribeMenu'>
}

function reportNavigationFailure(error: unknown) {
    dialogService.error(error, { fallbackMessage: 'Diagram navigation failed' })
}

function diagramTitle(record: DiagramRecord, actions: readonly ActionDefinition[]) {
    const label = actions.find(({ id }) => id === record.actionId)?.label ?? record.label

    return record.createdAt ? `${label} - ${new Date(record.createdAt).toLocaleString()}` : label
}

function submenuKind(element: HTMLElement): DiagramItemSubmenuKind {
    const kind = element.dataset.diagramSubmenu
    if (kind !== 'actions' && kind !== 'savedDiagrams') throw new Error('Diagram menu item is missing its submenu')

    return kind
}

/** Item actions and saved child diagrams, subscribed independently from the diagram surface. */
export function DiagramItemMenu({ emphasis = diagramEmphasisService, service }: DiagramItemMenuProps) {
    const menu = useSyncExternalStore(service.subscribeMenu, service.getMenuSnapshot, service.getMenuSnapshot)
    const { actions } = useActions()
    const selectedContext = useMemo(() => menu
        ? diagramContext('child', menu.diagramId, menu.itemId, menu.itemLabel)
        : null, [menu])
    const childActions = useMemo(
        () => selectedContext ? actionsForContext(actions, selectedContext) : [],
        [actions, selectedContext],
    )
    const savedChildren = menu?.surface === 'current' ? service.getSavedChildren(menu.diagramId, menu.itemId) : []
    const handleClose = () => service.closeItemMenu()
    const handleCloseSubmenu = () => {
        const anchorElement = menu?.submenu?.anchorElement
        service.closeItemSubmenu()
        anchorElement?.focus()
    }
    const handleOpenSubmenu = (event: MouseEvent<HTMLElement>) => {
        service.openItemSubmenu(submenuKind(event.currentTarget), event.currentTarget)
    }
    const handleParentKeyDown = (event: KeyboardEvent<HTMLElement>) => {
        if (event.key !== 'ArrowRight') return
        event.preventDefault()
        service.openItemSubmenu(submenuKind(event.currentTarget), event.currentTarget)
    }
    const handleNestedMenuKeyDown = (event: KeyboardEvent<HTMLElement>) => {
        if (event.key !== 'ArrowLeft') return
        event.preventDefault()
        event.stopPropagation()
        handleCloseSubmenu()
    }
    const handleActionClick = (event: MouseEvent<HTMLElement>) => {
        const actionId = event.currentTarget.dataset.actionId
        if (!actionId) throw new Error('Diagram action menu item is missing its action')
        service.openChildPopup(actionId)
    }
    const handleSavedDiagramClick = (event: MouseEvent<HTMLElement>) => {
        const diagramId = event.currentTarget.dataset.diagramId
        if (!diagramId) throw new Error('Saved diagram menu item is missing its diagram')
        void service.navigateToSavedDiagram(diagramId).catch(reportNavigationFailure)
    }
    const handleEmphasize = () => {
        if (!menu) return
        emphasis.emphasize({
            diagramId: menu.diagramId,
            objectId: menu.itemId,
            objectKind: menu.objectKind,
            surface: menu.surface,
        })
        service.closeItemMenu()
    }                    data-diagram-submenu="savedDiagrams"
                    onClick={handleOpenSubmenu}
                    onKeyDown={handleParentKeyDown}
                >
                    <ListItemText>Saved diagrams</ListItemText>
                    <ChevronRight fontSize="small" />
                </MenuItem> : null}
            </Menu>
            <Menu
                anchorEl={menu?.submenu?.anchorElement}
                anchorOrigin={{ horizontal: 'right', vertical: 'top' }}
                onClose={handleCloseSubmenu}
                open={!!activeSubmenu}
                slotProps={{
                    list: {
                        'aria-label': activeSubmenu === 'actions' ? 'Actions' : 'Saved diagrams',
                        onKeyDown: handleNestedMenuKeyDown,
                    },
                }}
                transformOrigin={{ horizontal: 'left', vertical: 'top' }}
            >
                {activeSubmenu === 'actions' ? (childActions.length > 0 ? childActions.map((action) => (
                    <MenuItem data-action-id={action.id} key={action.id} onClick={handleActionClick}>{action.label}</MenuItem>
                )) : <MenuItem disabled>No child actions</MenuItem>) : null}
                {activeSubmenu === 'savedDiagrams' ? (savedChildren.length > 0 ? savedChildren.map((record) => (
                    <MenuItem data-diagram-id={record.id} key={record.id} onClick={handleSavedDiagramClick}>
                        {diagramTitle(record, actions)}
                    </MenuItem>
                )) : <MenuItem disabled>No saved diagrams</MenuItem>) : null}
            </Menu>
        </>
    )
}

