export function NewDiagramMenu({ disabled, onCreateDiagram }: NewDiagramMenuProps) {
    const [anchorElement, setAnchorElement] = useState<HTMLElement | null>(null)

    const handleOpenMenu = (event: MouseEvent<HTMLButtonElement>) => {
